sect1.para:
    &php.ini; मा upload_tmp_dir
    directive मार्फत अर्को स्थान नतोकिएसम्म, files डिफल्ट रूपमा server को
    डिफल्ट temporary directory मा भण्डारण हुन्छन्। PHP चल्ने वातावरणमा
    TMPDIR environment variable सेट गरेर server को डिफल्ट
    directory परिवर्तन गर्न सकिन्छ। PHP script भित्रबाट putenv
    प्रयोग गरेर यसलाई सेट गर्दा काम गर्दैन। अन्य कार्यहरू पनि upload गरिएका
    files मा चलिरहेका छन् भनी सुनिश्चित गर्न पनि यो environment variable प्रयोग
    गर्न सकिन्छ।

     File uploads validate गर्ने


      थप जानकारीका लागि is_uploaded_file र
      move_uploaded_file function का विवरणहरू पनि
      हेर्नुहोस्। तलको उदाहरणले form बाट आएको file upload लाई process गर्नेछ।



<?php
$uploaddir = '/var/www/uploads/';
$uploadfile = $uploaddir . basename($_FILES['userfile']['name']);

echo '<pre>';
if (move_uploaded_file($_FILES['userfile']['tmp_name'], $uploadfile)) {
    echo "File is valid, and was successfully uploaded.\n";
} else {
    echo "Possible file upload attack!\n";
}

echo 'Here is some more debugging info:';
print_r($_FILES);

print "</pre>";

?>
